class Solution:
    def runningSum(self, nums: list) -> list:
        res = []
        curr = 0
        for n in nums:
            curr += n
            res.append(curr)
        return res

class Solution:
    def maximumWealth(self, accounts: list) -> int:
        return max(sum(row) for row in accounts)

class Solution:
    def shuffle(self, nums: list, n: int) -> list:
        res = []
        for i in range(n):
            res.append(nums[i])
            res.append(nums[i + n])
        return res

class Solution:
    def defangIPaddr(self, address: str) -> str:
        return address.replace('.', '[.]')

class Solution:
    def numJewelsInStones(self, jewels: str, stones: str) -> int:
        jset = set(jewels)
        return sum(1 for ch in stones if ch in jset)

class Solution:
    def scoreOfString(self, s: str) -> int:
        return sum(abs(ord(s[i]) - ord(s[i + 1])) for i in range(len(s) - 1))

class Solution:
    def uniqueOccurrences(self, arr: list) -> bool:
        from collections import Counter
        counts = list(Counter(arr).values())
        return len(counts) == len(set(counts))

class Solution:
    def findTheDifference(self, s: str, t: str) -> str:
        from collections import Counter
        diff = Counter(t) - Counter(s)
        return list(diff.keys())[0]

class Solution:
    def moveZeroes(self, nums: list) -> list:
        insert_pos = 0
        for num in nums:
            if num != 0:
                nums[insert_pos] = num
                insert_pos += 1
        while insert_pos < len(nums):
            nums[insert_pos] = 0
            insert_pos += 1
        return nums

class Solution:
    def reverseVowels(self, s: str) -> str:
        chars = list(s)
        vowels = set('aeiouAEIOU')
        i, j = 0, len(chars) - 1
        while i < j:
            while i < j and chars[i] not in vowels:
                i += 1
            while i < j and chars[j] not in vowels:
                j -= 1
            if i < j:
                chars[i], chars[j] = chars[j], chars[i]
                i += 1
                j -= 1
        return ''.join(chars)
